import { ABILITIES, progression, mod, signed, crLabel, eligibility, effectiveAC, effectiveAbilities, takeDamage, transform, rest, isCircleSpell, canCastInForm } from './rules.js';
import { animalArt, icon } from './art.js';

const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='moonwild.character.v1';
let beasts=[], spells=[], artworkCredits=null, state, pendingBackup=null, view={tab:'known',search:'',movement:'all',cr:'all',sort:'name',layout:'grid',spellSearch:''};
const defaultState=()=>({version:1,name:'Elowen Ashgrove',species:'Wood Elf',background:'Guide',level:6,maxHP:45,hp:45,tempHP:0,ac:15,abilities:{strength:10,dexterity:14,constitution:14,intelligence:12,wisdom:18,charisma:8},uses:3,slots:[4,3,3],known:['Brown Bear','Dire Wolf','Giant Spider','Saber-Toothed Tiger','Giant Constrictor Snake','Polar Bear'].map(n=>beasts.find(b=>b.name===n)?.key).filter(Boolean),favorites:[],prepared:['Entangle','Healing Word','Pass without Trace','Call Lightning'],active:null,concentration:'',notes:'',entries:[],activity:[],resurgenceUsed:false,moonSteps:4,primalOrder:'warden',cantrips:['Druidcraft','Guidance','Produce Flame'],equipment:'Leather armor, shield, quarterstaff, druidic focus, explorer’s pack, herbalism kit.'});
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Browser storage is unavailable. Export a backup to keep your changes.');}}
function log(message){state.activity.unshift({message,at:new Date().toISOString()});state.activity=state.activity.slice(0,20);save();}
let toastTimer; function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
const p=()=>progression(state.level), active=()=>beasts.find(b=>b.key===state.active), getBeast=key=>beasts.find(b=>b.key===key);
const btn=(label,action,cls='secondary',attrs='')=>`<button class="button ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
function normalize(s){
  const d=defaultState(); if(!s||s.version!==1) return d;
  s={...d,...s,abilities:{...d.abilities,...s.abilities}};
  s.level=Math.max(1,Math.min(20,Math.trunc(Number(s.level)||6)));
  for(const a of ABILITIES)s.abilities[a]=Math.max(1,Math.min(30,Number(s.abilities[a])||10));
  s.maxHP=Math.max(1,Math.min(999,Number(s.maxHP)||45));s.hp=Math.max(0,Math.min(s.maxHP,Number(s.hp)||0));s.tempHP=Math.max(0,Math.min(999,Number(s.tempHP)||0));
  s.ac=Math.max(1,Math.min(40,Number(s.ac)||15));
  s.uses=Math.max(0,Math.min(progression(s.level).uses,Number(s.uses)||0));
  s.slots=progression(s.level).slots.map((max,i)=>Math.max(0,Math.min(max,Number(s.slots?.[i])||0)));
  for(const k of ['known','favorites','prepared','entries','activity'])s[k]=Array.isArray(s[k])?s[k]:d[k];
  s.known=[...new Set(s.known)].filter(k=>getBeast(k)&&!eligibility(getBeast(k),s.level)).slice(0,progression(s.level).known);
  s.entries=s.entries.filter(e=>e&&typeof e.title==='string'&&typeof e.body==='string').map(e=>({title:e.title.slice(0,100),body:e.body,at:e.at||new Date().toISOString()}));s.activity=s.activity.filter(e=>e&&typeof e.message==='string').map(e=>({message:e.message,at:e.at||new Date().toISOString()}));s.shiftedAt=Number(s.shiftedAt)||null;s.favorites=s.favorites.filter(k=>getBeast(k));s.active=s.known.includes(s.active)?s.active:null;
  s.primalOrder=s.primalOrder==='magician'?'magician':'warden';s.cantrips=(Array.isArray(s.cantrips)?s.cantrips:d.cantrips).filter(n=>spells.some(t=>t.name===n&&t.level===0)).slice(0,progression(s.level).cantrips+(s.primalOrder==='magician'?1:0));s.equipment=String(s.equipment||'');s.moonSteps=Math.max(0,Math.min(Math.max(1,mod(s.abilities.wisdom)),Number(s.moonSteps)||0));s.prepared=s.prepared.filter(n=>spells.some(t=>t.name===n&&t.level>0&&t.level<=progression(s.level).slots.length&&!isCircleSpell(t,s.level)&&t.name!=='Speak with Animals')).slice(0,progression(s.level).prepared);s.notes=String(s.notes||'');s.name=String(s.name||d.name).slice(0,70);s.species=String(s.species||d.species).slice(0,70);s.background=String(s.background||d.background).slice(0,70);s.concentration=String(s.concentration||'');
  return s;
}
const nav=[['character','grid','Character sheet'],['wild-shape','paw','Wild Shape'],['spells','spark','Spellbook'],['journal','book','Field journal'],['progression','leaf','Progression']];
const page=()=>nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'wild-shape';
function render(){
  const route=page(), current=nav.find(n=>n[0]===route);
  $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#wild-shape"><img src="./assets/mark.svg" alt=""/><span>moonwild<span class="brand-sub">DRUID CHARACTER COMPANION</span></span></a>
    <div class="character-mini"><div class="avatar">${icon('leaf')}</div><strong>${esc(state.name)}</strong><span>Level ${state.level} · ${state.level>=3?'Circle of the Moon':'Druid'}</span><button class="text-button" data-action="edit-character">Manage character ${icon('chevrondown')}</button></div>
    <div class="nav-label">YOUR ADVENTURE</div><nav>${nav.map(([id,i,label])=>`<a href="#${id}" class="nav-link ${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='wild-shape'?'<span class="nav-count">'+state.known.length+'</span>':''}</a>`).join('')}</nav>
    <div class="sidebar-bottom"><button class="text-button" data-action="sources">${icon('info')} Rules & sources <span class="edition">5.5e</span></button><div class="saved"><span></span> Saved on this device</div></div></aside>
    <div class="workspace"><header class="topbar"><div class="breadcrumbs">My character ${icon('chevron')} <strong>${current[2]}</strong></div><div class="top-actions">${btn(icon('sun')+' Short rest','short-rest','quiet')}${btn(icon('moon')+' Long rest','long-rest','secondary') }<button class="round-avatar" aria-label="Edit character" data-action="edit-character">${esc(state.name.charAt(0))}</button></div></header>
    <main id="main-content">${route==='wild-shape'?wildPage():route==='character'?characterPage():route==='spells'?spellPage():route==='journal'?journalPage():progressionPage()}</main>
    <footer><span>D&D 5.5e · Saved locally</span><button class="text-button" data-action="backup">Restore backup</button><button class="text-button" data-action="export">${icon('download')} Export character</button></footer></div>`;
}
function pageHeading(eyebrow,title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function resourceStrip(){const q=p();return `<div class="resource-strip"><div class="resource"><span class="resource-symbol">${icon('moon')}</span><div><span class="label">Wild Shape uses</span><div class="resource-value"><span class="pips">${Array.from({length:q.uses},(_,i)=>`<span class="pip ${i<state.uses?'filled':''}"></span>`).join('')}</span><strong>${state.uses}<small> / ${q.uses}</small></strong></div></div></div>
  <div class="resource"><span class="resource-symbol">${icon('paw')}</span><div><span class="label">Maximum form CR</span><strong>CR ${crLabel(q.maxCR)}<small> ${state.level>=3?'Circle of the Moon':'Druid'}</small></strong></div></div>
  <div class="resource"><span class="resource-symbol">${icon('heart')}</span><div><span class="label">Temp HP on transformation</span><strong>+${q.tempHP}<small> temporary HP</small></strong></div></div>
  <div class="resource"><span class="resource-symbol">${icon('clock')}</span><div><span class="label">Form duration</span><strong>${q.hours}<small> hours per form</small></strong></div></div></div>`;}
function wildPage(){
  const q=p(), b=active();
  return pageHeading('LEVEL '+state.level+' · '+(state.level>=3?'CIRCLE OF THE MOON':'DRUID'),'Wild Shape','Choose a known form. Transform as a Bonus Action.',btn(icon('plus')+' Manage forms','manage-forms'))+
  resourceStrip()+
  (b?activePanel(b):`<div class="form-status">${icon('leaf')}<span><strong>Normal form</strong><span class="status-separator">·</span> ${state.hp} / ${state.maxHP} HP${state.tempHP?' · '+state.tempHP+' temporary HP':''}</span><span class="status-tag">${state.uses?'1 use per transformation':'No uses remaining · take a rest'}</span></div>`)+
  `<section class="forms-section"><div class="section-top"><div class="tabs" role="tablist" aria-label="Form collections">${[['known','Known forms',state.known.length],['library','Beast library',beasts.length],['favorites','Favorites',state.favorites.length]].map(([id,label,n])=>`<button role="tab" aria-selected="${view.tab===id}" tabindex="${view.tab===id?0:-1}" aria-controls="form-results" id="tab-${id}" class="tab ${view.tab===id?'selected':''}" data-action="tab" data-value="${id}">${label} <span>${n}</span></button>`).join('')}</div><span class="collection-note">${state.known.length} of ${q.known} forms learned</span></div>
  <div class="filterbar"><label class="search-field">${icon('search')}<input id="form-search" type="search" placeholder="Search forms…" value="${esc(view.search)}" aria-label="Search beast forms"><span class="key-hint">/</span></label><select id="movement-filter" aria-label="Filter by movement">${[['all','Any movement'],['walk','Land'],['swim','Swimming'],['fly','Flying'],['climb','Climbing']].map(([v,t])=>`<option value="${v}" ${view.movement===v?'selected':''}>${t}</option>`).join('')}</select><select id="cr-filter" aria-label="Filter by eligibility"><option value="all" ${view.cr==='all'?'selected':''}>Any CR</option><option value="eligible" ${view.cr==='eligible'?'selected':''}>Eligible at my level</option>${[0,.125,.25,.5,1,2,3,4,5,6,8].map(n=>`<option value="${n}" ${view.cr===String(n)?'selected':''}>CR ${crLabel(n)}</option>`).join('')}</select><div class="view-toggle"><button aria-label="Grid view" aria-pressed="${view.layout==='grid'}" data-action="layout" data-value="grid">${icon('grid')}</button><button aria-label="List view" aria-pressed="${view.layout==='list'}" data-action="layout" data-value="list">${icon('list')}</button></div></div>
  <div class="results-line"><span id="result-count"></span><label>Sort by <select id="sort-forms" aria-label="Sort forms">${[['name','Name'],['cr','Challenge rating'],['ac','Armor class']].map(([v,t])=>`<option value="${v}" ${view.sort===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div id="form-results"></div></section>
  <details class="rules-note"><summary>How Wild Shape works</summary><div><p>You retain your own HP and mental abilities. Moon forms use the higher of the Beast’s AC or 13 + your Wisdom modifier, and gain 3 × druid level temporary HP. Before subclass level 3, use the base Druid rules. Flight unlocks at level 8.</p><button class="text-button" data-action="sources">Full rules & sources ${icon('arrow')}</button></div></details>`;
}
function updateForms(){if(!$('#form-results'))return;
  let list=beasts.filter(b=>(view.tab==='known'?state.known.includes(b.key):view.tab==='favorites'?state.favorites.includes(b.key):true)&&b.name.toLowerCase().includes(view.search.toLowerCase())&&(view.movement==='all'||b.speed[view.movement]>0)&&(view.cr==='all'||(view.cr==='eligible'?!eligibility(b,state.level):b.challenge_rating===Number(view.cr))));
  list.sort((a,b)=>view.sort==='cr'?a.challenge_rating-b.challenge_rating||a.name.localeCompare(b.name):view.sort==='ac'?effectiveAC(b,state)-effectiveAC(a,state):a.name.localeCompare(b.name));
  $('#result-count').textContent=`${list.length} ${list.length===1?'form':'forms'} ${view.tab==='known'?'in your collection':'to discover'}`;
  $('#form-results').setAttribute('role','tabpanel');$('#form-results').setAttribute('aria-labelledby','tab-'+view.tab);$('#form-results').className=`form-grid ${view.layout==='list'?'list-layout':''}`;
  $('#form-results').innerHTML=list.length?list.map(formCard).join(''):`<div class="empty-state">${icon('paw')}<h3>No matching forms</h3><p>${view.tab==='known'&&!state.known.length?'Use Manage forms to learn your first Beast forms.':view.tab==='favorites'?'Star a form to keep it close at hand, or adjust your filters.':'Try a different search or clear your filters.'}</p>${btn('Reset filters','clear-filters','secondary')}</div>`;
}
function formCard(b){
  const reason=eligibility(b,state.level),known=state.known.includes(b.key),fav=state.favorites.includes(b.key),isActive=state.active===b.key;
  const attacks=b.actions.flatMap(a=>a.attacks||[]).map(a=>a.to_hit_mod).filter(Number.isFinite);
  const attack=attacks.length?signed(Math.max(...attacks)):'—';
  const movement=Object.entries(b.speed).filter(([k,v])=>k!=='unit'&&k!=='walk'&&typeof v==='number'&&v>0).map(([k,v])=>k[0].toUpperCase()+k.slice(1)+' '+v+' ft.');
  const traits=[...movement,...b.traits.map(t=>t.name)].slice(0,2);
  const unavailable=reason||(known&&!state.uses?'No Wild Shape uses remaining.':known&&!state.hp?'You must have HP to transform.':null);
  return `<article class="form-card ${reason?'locked':''} ${isActive?'current':''}">
    <button class="card-art" data-action="beast-details" data-key="${b.key}" aria-label="View ${esc(b.name)} stat block">${animalArt(b.name)}<span class="cr-badge">CR ${crLabel(b.challenge_rating)}</span>${isActive?'<span class="active-badge">Current form</span>':''}</button>
    <button class="favorite ${fav?'is-favorite':''}" data-action="favorite" data-key="${b.key}" aria-label="${fav?'Unfavorite':'Favorite'} ${esc(b.name)}" aria-pressed="${fav}">${icon('star')}</button>
    <div class="card-body"><div class="card-title"><button class="title-button" data-action="beast-details" data-key="${b.key}">${esc(b.name)}</button>${known?'<span class="known-mark" title="Known form">'+icon('check')+'</span>':''}</div>
    <p class="beast-type">${b.size.name} Beast <span>·</span> ${roleLabel(b)}</p>
    <dl class="card-stats"><div><dt>Armor class</dt><dd>${effectiveAC(b,state)}${state.level>=3&&effectiveAC(b,state)>b.armor_class?'<small>Moon</small>':''}</dd></div><div><dt>Speed</dt><dd>${b.speed.walk||b.speed.swim||b.speed.fly||0}<small>ft.</small></dd></div><div><dt>Attack bonus</dt><dd>${attack}</dd></div></dl>
    <div class="card-traits">${traits.map(t=>'<span>'+esc(t)+'</span>').join('')}</div>
    <div class="card-actions">${known&&!reason?btn(isActive?'Transform again':'Transform','transform','primary',`data-key="${b.key}" ${unavailable?'disabled title="'+esc(unavailable)+'"':''}`):''}${btn('View details','beast-details','secondary',`data-key="${b.key}"`)}</div>
    ${unavailable?'<p class="lock-reason">'+icon(reason?'lock':'info')+esc(unavailable)+'</p>':''}</div></article>`;
}
function roleLabel(b){return b.speed.fly?'Aerial scout':b.speed.swim?'Water explorer':b.speed.climb?'Agile explorer':b.challenge_rating>=1?'Frontline companion':'Quiet explorer';}
function activePanel(b){return `<section class="active-panel" id="active-form"><div class="active-thumbnail">${animalArt(b.name)}</div><div class="active-copy"><div class="eyebrow">${icon('moon')} CURRENTLY TRANSFORMED</div><h3>${esc(b.name)}</h3><p>AC ${effectiveAC(b,state)} · ${state.hp}/${state.maxHP} HP · ${state.tempHP} temporary HP · <span id="shape-timer">${remainingTime()}</span></p>${state.level>=6?`<span class="small">Radiant attacks available · CON save ${signed(constitutionSave(b))}</span>`:''}</div><div class="active-buttons">${btn('Take damage','damage','secondary')}${btn('Stat block','beast-details','secondary',`data-key="${b.key}"`)}${btn('Revert','revert','primary')}</div></section>`;}
function remainingTime(){const left=Math.max(0,p().hours*3600000-(Date.now()-(state.shiftedAt||Date.now())));return left?`${Math.floor(left/3600000)}h ${Math.floor(left%3600000/60000)}m left`:'Duration ended · revert';}
function constitutionSave(b){return Math.max(b.saving_throws?.constitution??mod(b.ability_scores.constitution),mod(b.ability_scores.constitution))+(state.level>=6?mod(state.abilities.wisdom):0);}
function cantripLimit(){return p().cantrips+(state.primalOrder==='magician'?1:0);}
function characterPage(){const b=active(),scores=b?effectiveAbilities(b,state):state.abilities;return pageHeading('YOUR ROOTS, YOUR STORY',esc(state.name),`${esc(state.species)} · ${esc(state.background)} · Level ${state.level} ${state.level>=3?'Circle of the Moon druid':'druid'}`,btn(icon('edit')+' Edit character','edit-character'))+
  `<div class="character-overview"><section class="panel vitality"><div class="panel-heading"><h2>${icon('heart')} Vitality</h2><span class="badge">${b?esc(b.name):'Humanoid form'}</span></div><div class="hp-number">${state.hp}<span> / ${state.maxHP}</span></div><div class="hp-track"><span style="width:${state.hp/state.maxHP*100}%"></span></div><p>${state.tempHP} temporary HP <button class="text-button" data-action="temp-hp">Adjust</button></p><div class="button-row">${btn('Take damage','damage','secondary')}${btn('Heal','heal','primary')}</div></section><section class="panel"><div class="panel-heading"><h2>At a glance</h2>${icon('shield')}</div><div class="quick-stats">${[['Armor class',b?effectiveAC(b,state):state.ac],['Proficiency',signed(p().proficiency)],['Spell save DC',8+p().proficiency+mod(state.abilities.wisdom)],['Spell attack',signed(p().proficiency+mod(state.abilities.wisdom))]].map(([k,v])=>`<div><strong>${v}</strong><span>${k}</span></div>`).join('')}</div></section></div>
  ${b?activePanel(b):''}<div class="ability-grid">${ABILITIES.map(a=>`<button class="ability-card" data-action="roll-ability" data-value="${a}"><span>${a.slice(0,3).toUpperCase()}</span><strong>${signed(mod(scores[a]))}</strong><small>${scores[a]} ${b&&['intelligence','wisdom','charisma'].includes(a)?'· retained':''}</small></button>`).join('')}</div>
  <div class="two-column"><section class="panel"><div class="panel-heading"><h2>${icon('moon')} Wild Shape</h2><a class="text-button" href="#wild-shape">View forms ${icon('arrow')}</a></div><p>${state.uses} of ${p().uses} uses available · ${state.known.length} forms learned</p>${slotPips(state.uses,p().uses)}<p class="muted">A Short Rest restores one use. A Long Rest restores all uses.</p>${state.level>=5?`<div class="divider"></div><h3>Wild Resurgence</h3><p class="muted">When you have no uses, spend a spell slot to regain one (once per turn). Or spend a use to recover a level 1 slot once per Long Rest.</p><div class="button-row">${btn('Slot → Wild Shape','resurge','secondary',state.uses?'disabled':'')}${btn('Wild Shape → slot','recover-slot','secondary',state.resurgenceUsed||!state.uses||state.slots[0]>=p().slots[0]?'disabled':'')}</div>`:''}</section>
  <section class="panel"><div class="panel-heading"><h2>${icon('spark')} Spell resources</h2><a href="#spells" class="text-button">Spellbook ${icon('arrow')}</a></div>${slotRows()}<label class="field">Concentration <input id="concentration" value="${esc(state.concentration)}" placeholder="No active concentration"></label>${state.concentration?btn('End concentration','end-concentration','quiet'):''}</section></div>
  ${state.level>=10?`<section class="panel"><div class="panel-heading"><h2>Moonlight Step</h2><span>${state.moonSteps} / ${Math.max(1,mod(state.abilities.wisdom))} uses</span></div><p>Bonus Action: teleport up to 30 feet; your next attack this turn has Advantage.${state.level>=14?' Lunar Form lets a nearby willing creature come with you.':''}</p>${btn('Use Moonlight Step','moon-step','primary',!state.moonSteps?'disabled':'')}</section>`:''}
  <section class="panel"><div class="panel-heading"><h2>Equipment & traits</h2><span class="badge">${state.primalOrder==='magician'?'Magician':'Warden'}</span></div><textarea id="equipment-notes" rows="4" aria-label="Equipment and traits" placeholder="Track equipment, coins, feats, and personal traits…">${esc(state.equipment)}</textarea></section><section class="panel"><div class="panel-heading"><h2>Recent activity</h2>${btn(icon('dice')+' Roll d20','roll','quiet')}</div>${state.activity.length?state.activity.slice(0,6).map(e=>`<div class="activity-row"><span>${esc(e.message)}</span><time>${new Date(e.at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</time></div>`).join(''):'<p class="muted">Your next adventure starts here. Transform, cast, or roll a die to leave a trail.</p>'}</section>`;}
function slotPips(n,max){return `<div class="pips large">${Array.from({length:max},(_,i)=>`<span class="pip ${i<n?'filled':''}"></span>`).join('')}</div>`;}
function slotRows(){return p().slots.map((max,i)=>`<div class="slot-row"><span>Level ${i+1}</span><div>${slotPips(state.slots[i],max)}</div><strong>${state.slots[i]}/${max}</strong><button class="mini-button" aria-label="Spend level ${i+1} slot" data-action="spend-slot" data-value="${i}" ${!state.slots[i]?'disabled':''}>${icon('minus')}</button><button class="mini-button" aria-label="Restore level ${i+1} slot" data-action="restore-slot" data-value="${i}" ${state.slots[i]>=max?'disabled':''}>${icon('plus')}</button></div>`).join('');}
function spellPage(){return pageHeading('A LITTLE PRACTICAL MAGIC','Spellbook','Keep your magic close, even when your claws are out.')+`<div class="two-column spell-overview"><section class="panel"><div class="panel-heading"><h2>Spell slots</h2><span class="badge">DC ${8+p().proficiency+mod(state.abilities.wisdom)}</span></div>${slotRows()}</section><section class="panel circle-note">${icon('moon')}<h2>Moon magic, in any shape.</h2><p>Your circle spells are always prepared and can be cast in Wild Shape. Other spells require your normal form until level 18.</p><label class="field">Concentration <input id="concentration" placeholder="No active concentration" value="${esc(state.concentration)}"></label>${state.concentration?btn('End concentration','end-concentration','secondary'):''}<p class="small muted">Prepare spells during setup or after a Long Rest. Learn cantrips during setup or level-up. ${state.prepared.length}/${p().prepared} spells prepared · ${state.cantrips.length}/${cantripLimit()} cantrips learned (circle spells are extra).</p></section></div><div class="spell-tools"><label class="search-field">${icon('search')}<input type="search" id="spell-search" placeholder="Search the druid spellbook…" value="${esc(view.spellSearch)}" aria-label="Search spells"></label><span class="muted">SRD 5.2 · Prepared spells appear first</span></div><div id="spell-results"></div><div class="rules-note">${icon('info')}<p><strong>Fount of Moonlight</strong> is a level-7 circle spell outside the SRD. Refer to your 2024 Player’s Handbook for its spell text; track its level 4 slot above.</p></div>`;}
function updateSpells(){if(!$('#spell-results'))return; const list=spells.filter(s=>s.level<=p().slots.length&&s.name.toLowerCase().includes(view.spellSearch.toLowerCase())).sort((a,b)=>(Number(isCircleSpell(b,state.level)||state.prepared.includes(b.name)||state.cantrips.includes(b.name)||b.name==='Speak with Animals')-Number(isCircleSpell(a,state.level)||state.prepared.includes(a.name)||state.cantrips.includes(a.name)||a.name==='Speak with Animals'))||a.level-b.level||a.name.localeCompare(b.name));
  $('#spell-results').innerHTML=list.length?list.map(s=>{const circle=isCircleSpell(s,state.level),always=circle||s.name==='Speak with Animals',prepared=always||state.prepared.includes(s.name)||(!s.level&&state.cantrips.includes(s.name)),blocked=active()&&!canCastInForm(s,state.level);return `<article class="spell-row"><div class="spell-emblem">${icon(circle?'moon':'spark')}</div><div class="spell-copy"><button class="title-button" data-action="spell-detail" data-key="${s.key}">${esc(s.name)}</button><p>${s.level?'Level '+s.level:'Cantrip'} · ${esc(s.school.name)} · ${esc(s.casting_time.replaceAll('_',' '))}${s.concentration?' · Concentration':''}${s.ritual?' · Ritual':''}</p></div>${always?'<span class="badge">'+(circle?'Circle spell':'Always prepared')+'</span>':s.level?`<button class="prepare-toggle ${prepared?'prepared':''}" data-action="prepare-spell" data-key="${s.key}" aria-pressed="${prepared}">${prepared?icon('check')+' Prepared':'+ Prepare'}</button>`:`<button class="prepare-toggle ${prepared?'prepared':''}" data-action="learn-cantrip" data-key="${s.key}" aria-pressed="${prepared}">${prepared?icon('check')+' Learned':'+ Learn'}</button>`}${btn('Cast','cast','secondary',`data-key="${s.key}" ${blocked||!prepared||s.level&&!state.slots.some((n,i)=>i>=s.level-1&&n>0)?'disabled':''} title="${blocked?'Cannot cast this spell in your current form':'Cast spell'}"`)}</article>`;}).join(''):'<div class="empty-state"><h3>No spells found</h3><p>Try another name.</p></div>';}
function journalPage(){return pageHeading('LEAVE A LITTLE OF YOUR STORY','Field journal','Remember the places, creatures, and people worth returning to.',btn(icon('plus')+' New entry','new-entry'))+`<section class="panel"><div class="panel-heading"><h2>Campaign notes</h2><span class="saved"><span></span> Autosaved</span></div><textarea id="campaign-notes" aria-label="Campaign notes" rows="7" placeholder="A trail to follow. A promise to keep. A peculiar mushroom…">${esc(state.notes)}</textarea></section><div class="journal-entries">${state.entries.length?state.entries.map((e,i)=>`<article class="panel journal-entry"><div class="panel-heading"><time>${new Date(e.at).toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})}</time><button class="mini-button" data-action="delete-entry" data-value="${i}" aria-label="Delete entry ${esc(e.title)}">${icon('close')}</button></div><h2>${esc(e.title)}</h2><p>${esc(e.body)}</p></article>`).join(''):`<div class="journal-empty">${icon('book')}<h2>Every adventure leaves a story.</h2><p>Capture a new form, a close call, or a quiet moment under the moon.</p>${btn('Write your first entry','new-entry','primary')}</div>`}</div>`;}
const milestones=[[2,'Wild Shape','Your first four forms. Shift as a Bonus Action.'],[3,'Circle of the Moon','CR scales with level; improved AC and temporary HP. Cast circle spells while transformed.'],[5,'Wild Resurgence','Trade a spell slot for a use when empty; recover a level 1 slot once per Long Rest.'],[6,'Improved Circle Forms','Radiant attack damage option; add Wisdom to Constitution saves in Beast form.'],[7,'Elemental Fury','Choose Primal Strike for +1d8 elemental damage once on your turn, or Potent Spellcasting.'],[8,'Take to the sky','Flying forms and eight known forms.'],[10,'Moonlight Step','A 30-foot teleport as a Bonus Action, with uses based on Wisdom.'],[14,'Lunar Form','Once per turn, add 2d10 Radiant damage on a Beast-form attack hit. Bring an ally with Moonlight Step.'],[15,'Improved Elemental Fury','Primal Strike becomes 2d8; Potent Spellcasting gains more cantrip range.'],[18,'Beast Spells','Cast other spells in form, except those with costly or consumed Material components.'],[20,'Archdruid','When initiative begins with no Wild Shape uses, regain one. Nature Magician converts uses into a spell slot once per Long Rest.']];
function progressionPage(){return pageHeading('GROW INTO YOUR WILD','The path of the moon','Your druid level shapes the possibilities ahead.',btn('Change level','edit-character'))+resourceStrip()+`<div class="progression-layout"><section class="panel timeline"><h2>Your circle’s journey</h2>${milestones.map(([level,title,desc])=>`<div class="milestone ${state.level>=level?'unlocked':''}"><span class="milestone-dot">${state.level>=level?icon('check'):level}</span><div><span class="eyebrow">LEVEL ${level} ${state.level>=level?'· UNLOCKED':''}</span><h3>${title}</h3><p>${desc}</p></div></div>`).join('')}</section><section class="panel progression-table"><h2>Circle Forms at a glance</h2><table><thead><tr><th>Druid level</th><th>Max CR</th><th>Temp HP</th></tr></thead><tbody>${[2,3,6,9,12,15,18,20].map(l=>`<tr class="${state.level===l?'highlight':''}"><td>${l}</td><td>${crLabel(progression(l).maxCR)}</td><td>${progression(l).tempHP}</td></tr>`).join('')}</tbody></table><p class="small muted">Before level 3, use the base Druid limits. Swimming has no level restriction. Flying requires level 8. Level changes do not grant a free rest.</p><button class="text-button" data-action="sources">Read the sources ${icon('arrow')}</button></section></div>`;}
function refresh(){render();updateForms();updateSpells();}
function modal(title,body,wide=false){const d=$('#modal'); d.innerHTML=`<div class="modal-header"><h2 id="dialog-title">${title}</h2><button class="mini-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;d.className=wide?'wide':'';d.setAttribute('aria-labelledby','dialog-title');if(!d.open)d.showModal();}
function details(key){const b=getBeast(key);if(!b)return;const scores=effectiveAbilities(b,state);modal(esc(b.name),`<div class="detail-top">${animalArt(b.name)}<div><span class="eyebrow">${b.size.name} BEAST · CR ${crLabel(b.challenge_rating)}</span><h3>${roleLabel(b)}</h3><p>${eligibility(b,state.level)||'Eligible at your druid level'}</p><p><strong>AC ${effectiveAC(b,state)}</strong> (${b.armor_class} natural${state.level>=3?'; Moon AC applied if higher':''})</p><p><strong>${Object.entries(b.speed).filter(([k,v])=>k!=='unit'&&typeof v==='number'&&v>0).map(([k,v])=>`${k} ${v} ft.`).join(' · ')}</strong></p><p>You retain ${state.hp}/${state.maxHP} HP; gain ${p().tempHP} temp HP. Beast HP (${b.hit_points}) is reference only.</p></div></div><div class="ability-grid compact">${ABILITIES.map(a=>`<div class="ability-card"><span>${a.slice(0,3).toUpperCase()}</span><strong>${signed(mod(scores[a]))}</strong><small>${scores[a]}${['intelligence','wisdom','charisma'].includes(a)?' · you':''}</small></div>`).join('')}</div><p class="small muted">Beast skill bonuses: ${Object.entries(b.skill_bonuses||{}).map(([k,v])=>esc(k.replaceAll('_',' '))+' '+signed(v)).join(', ')||'None'}. Keep your own proficiencies; use your Proficiency Bonus and the higher applicable modifier. ${state.level>=6?'In form, your Moon CON save is '+signed(constitutionSave(b))+'.':''}</p>${b.traits.length?'<h3>Traits</h3>':''}${b.traits.map(t=>`<p><strong>${esc(t.name)}.</strong> ${esc(t.desc)}</p>`).join('')}<div class="image-credit-link"><button class="text-button" data-action="image-credits" data-value="${esc(b.name)}">Image source & credit ${icon('info')}</button></div><h3>Actions</h3>${b.actions.map(a=>`<div class="action-block"><strong>${esc(a.name)}</strong><p>${esc(a.desc)}</p></div>`).join('')}<div class="source-line">SRD 5.2 · Wizards of the Coast · CC BY 4.0 · via <a href="https://api.open5e.com/v2/creatures/${b.key}/" target="_blank" rel="noopener">Open5e ${icon('arrow')}</a></div><div class="modal-footer">${btn(state.favorites.includes(key)?'Remove favorite':'Favorite form','favorite','secondary',`data-key="${key}"`)}${btn('Transform','transform','primary',`data-key="${key}" ${eligibility(b,state.level)||!state.known.includes(key)||!state.uses||!state.hp?'disabled':''}`)}</div>`,true);}
function editCharacter(){modal('Edit character',`<form id="character-form"><div class="form-grid-fields"><label class="field full">Character name<input name="name" value="${esc(state.name)}" maxlength="70" required></label><label class="field">Species<input name="species" value="${esc(state.species)}" maxlength="70" required></label><label class="field">Background<input name="background" value="${esc(state.background)}" maxlength="70" required></label><label class="field">Druid level<input type="number" name="level" min="1" max="20" value="${state.level}" required></label><label class="field">Maximum HP<input type="number" name="maxHP" min="1" max="999" value="${state.maxHP}" required></label><label class="field">Normal armor class<input type="number" name="ac" min="1" max="40" value="${state.ac}" required></label></div><label class="field">Primal Order<select name="primalOrder"><option value="warden" ${state.primalOrder==='warden'?'selected':''}>Warden · martial weapons and medium armor</option><option value="magician" ${state.primalOrder==='magician'?'selected':''}>Magician · one extra cantrip</option></select></label><h3>Ability scores</h3><div class="ability-inputs">${ABILITIES.map(a=>`<label class="field">${a.slice(0,3).toUpperCase()}<input type="number" min="1" max="30" name="${a}" value="${state.abilities[a]}" required></label>`).join('')}</div><p class="small muted">Moon features start at level 3. Level changes update limits and remove ineligible forms. Adjust HP after leveling; resting restores newly gained resources.</p><div class="modal-footer">${btn('Cancel','close-modal')}<button class="button primary" type="submit">Save character</button></div></form>`);}
function manageForms(){const eligible=beasts.filter(b=>!eligibility(b,state.level));modal('Your known forms',`<p>Choose up to <strong>${p().known} forms</strong> for character setup or to fill newly unlocked spaces after leveling.</p><p class="small muted">During play, use the Long Rest dialog to replace one known form. These setup controls let you correct your character sheet.</p><form id="known-form"><div class="known-picker">${eligible.map(b=>`<label class="known-choice"><input type="checkbox" name="known" value="${b.key}" ${state.known.includes(b.key)?'checked':''}><span>${esc(b.name)}</span><span class="badge">CR ${crLabel(b.challenge_rating)}</span></label>`).join('')||'<p>Wild Shape unlocks at druid level 2.</p>'}</div><p id="known-count" class="small">${state.known.length} / ${p().known} selected</p><div class="modal-footer">${btn('Cancel','close-modal')}<button class="button primary" type="submit">Save known forms</button></div></form>`,true);}
function restDialog(type){const long=type==='long';modal(long?'Complete a Long Rest':'Complete a Short Rest',`<p>${long?'Complete a Long Rest to restore your HP, spell slots, Wild Shape uses, and Moonlight Step uses. Your current form and concentration end.':'Complete a Short Rest to regain one expended Wild Shape use. Apply any healing from spent Hit Dice separately on your character sheet.'}</p><form id="rest-form" data-type="${type}">${long?`<div class="rest-swap"><h3>Trade one familiar shape for another</h3><p class="small muted">Optional: replace one known form with an eligible Beast.</p><label class="field">Forget<select name="forget"><option value="">Keep my current forms</option>${state.known.map(k=>`<option value="${k}">${esc(getBeast(k).name)}</option>`).join('')}</select></label><label class="field">Learn<select name="learn"><option value="">Choose a replacement</option>${beasts.filter(b=>!eligibility(b,state.level)&&!state.known.includes(b.key)).map(b=>`<option value="${b.key}">${esc(b.name)} · CR ${crLabel(b.challenge_rating)}</option>`).join('')}</select></label></div>`:''}<div class="modal-footer">${btn('Cancel','close-modal')}<button class="button primary" type="submit">${icon(long?'moon':'sun')} Complete ${long?'Long':'Short'} Rest</button></div></form>`);}
function amountDialog(type){modal(type==='damage'?'Take damage':type==='heal'?'Restore hit points':'Temporary hit points',`<form id="amount-form" data-type="${type}"><p>${type==='damage'?'Damage is absorbed by temporary HP first. Any remainder reduces your character’s HP.':type==='heal'?'Restore your character’s HP, up to your maximum. Healing does not restore temporary HP.':'Set your temporary HP total. Temporary HP never adds together.'}</p><label class="field">${type==='temp-hp'?'Temporary HP total':'Amount'}<input type="number" name="amount" min="${type==='temp-hp'?0:1}" max="999" value="${type==='temp-hp'?state.tempHP:1}" required autofocus></label><div class="modal-footer">${btn('Cancel','close-modal')}<button class="button primary" type="submit">Apply</button></div></form>`);}
function spellDetail(key){const s=spells.find(s=>s.key===key);if(!s)return;modal(esc(s.name),`<span class="badge">${s.level?'Level '+s.level:'Cantrip'} · ${esc(s.school.name)}</span><p><strong>Casting time:</strong> ${esc(s.casting_time.replaceAll('_',' '))}<br><strong>Range:</strong> ${esc(s.range_text)}<br><strong>Duration:</strong> ${s.concentration?'Concentration, ':''}${esc(s.duration)}<br><strong>Components:</strong> ${[s.verbal?'V':'',s.somatic?'S':'',s.material?'M ('+s.material_specified+')':''].filter(Boolean).map(esc).join(', ')}</p><div class="spell-description">${esc(s.desc)}</div>${s.higher_level?`<p><strong>Higher levels.</strong> ${esc(s.higher_level)}</p>`:''}<p class="source-line">SRD 5.2 · Wizards of the Coast · CC BY 4.0 · Open5e</p><div class="modal-footer">${btn('Close','close-modal')}${btn('Cast spell','cast','primary',`data-key="${s.key}"`)}</div>`);}
function castDialog(key){const s=spells.find(s=>s.key===key);if(!s)return;if(active()&&!canCastInForm(s,state.level))return toast('Revert before casting this spell.');if(s.level&&!state.prepared.includes(s.name)&&!isCircleSpell(s,state.level)&&s.name!=='Speak with Animals')return toast('Prepare this spell during setup or after a Long Rest.');if(!s.level){if(!state.cantrips.includes(s.name)&&!isCircleSpell(s,state.level))return toast('Learn this cantrip during setup or level-up first.');if(s.concentration)state.concentration=s.name;log('Cast '+s.name+'.');toast(s.name+' cast.');refresh();$('#modal').close();return;}
  const options=p().slots.map((_,i)=>i+1>=s.level&&state.slots[i]>0?`<option value="${i}">Level ${i+1} · ${state.slots[i]} remaining</option>`:'').join('');if(!options)return toast('No suitable spell slots remain.');modal('Cast '+esc(s.name),`<form id="cast-form" data-key="${key}"><label class="field">Spell slot<select name="slot">${options}</select></label>${s.concentration?`<p class="small muted">This requires concentration.${state.concentration?' It will replace '+esc(state.concentration)+'.':''}</p>`:''}<p class="small muted">This tracks the slot and concentration. Resolve the spell’s attacks, saves, healing, and damage at the table.</p><div class="modal-footer">${btn('Cancel','close-modal')}<button type="submit" class="button primary">Cast spell</button></div></form>`);}
function sources(){modal('Rules & sources',`<p>Moonwild uses <strong>D&D 5.5e (the 2024 rules)</strong>, with Circle of the Moon features beginning at druid level 3. Character resources assume a single-class druid.</p><div class="source-card"><h3>Beasts & spells</h3><p>Bundled SRD 5.2 records from <a href="https://open5e.com/" target="_blank" rel="noopener">Open5e</a>, retrieved October 16, 2026. Swarms are excluded from the form library. No 2014 stat blocks are mixed in.</p><p>This work includes material taken from the System Reference Document 5.2 (“SRD 5.2”) by Wizards of the Coast LLC, available at <a href="https://www.dndbeyond.com/srd" target="_blank" rel="noopener">dndbeyond.com/srd</a>. The SRD 5.2 is licensed under the <a href="https://creativecommons.org/licenses/by/4.0/legalcode" target="_blank" rel="noopener">Creative Commons Attribution 4.0 International License</a>. Changes: presentation, filtering, and derived character statistics.</p></div><div class="source-card"><h3>Druid & Circle of the Moon</h3><p>Progression checked against the <a href="https://www.dndbeyond.com/sources/dnd/br-2024/character-classes#Druid" target="_blank" rel="noopener">2024 Druid rules</a> and the official <a href="https://www.dndbeyond.com/posts/1755-the-2024-circle-of-the-moon-druid-and-changes-to" target="_blank" rel="noopener">Circle of the Moon overview</a>. Subclass features are summarized; consult your Player’s Handbook for full text and table rulings.</p></div><p class="small muted">Moonwild is an independent companion, unaffiliated with Wizards of the Coast. Data stays in this browser. Use Export character for backups. Form images combine AI-generated naturalistic artwork, licensed wildlife photographs, and prehistoric life reconstructions. Photographs used for giant forms are species references; stat blocks determine size and game statistics.</p><div class="modal-footer">${btn('Artwork credits','image-credits','secondary')}${btn('Close','close-modal','primary')}</div>`,true);}
async function showImageCredits(name){
  try {
    if(!artworkCredits){const response=await fetch('./data/artwork.json');if(!response.ok)throw Error('Image credits are unavailable.');artworkCredits=await response.json();}
    const credits=name?artworkCredits.images.filter(c=>c.name===name):artworkCredits.images;
    const safeLink=url=>/^https:\/\//.test(url||'')?esc(url):'#';
    modal(name?esc(name)+' · image credit':'Artwork credits',`<p>44 generated images and 41 licensed animal references. Naturalistic artwork illustrates the form; rules determine its size and capabilities.</p>${credits.map(c=>'<div class="art-credit"><img src="'+esc(c.file)+'" alt="'+esc(c.name)+'" loading="lazy" width="100" height="75"><div><h3>'+esc(c.name)+'</h3><p>'+esc(c.kind)+' · '+esc(c.author||'Generated with OpenAI image generation')+'</p>'+(c.source?'<a href="'+safeLink(c.source)+'" target="_blank" rel="noopener">Original source</a> · <a href="'+safeLink(c.licenseUrl)+'" target="_blank" rel="noopener">'+esc(c.license)+'</a>':'<p>Original generated artwork for Moonwild.</p>')+'<p class="small muted">'+esc(c.changes||'Encoded as local WebP.')+'</p></div></div>').join('')}<div class="modal-footer">${btn('Close','close-modal','primary')}</div>`,true);
  }catch(error){toast(error.message);}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,key=el.dataset.key,value=el.dataset.value;
  if(a==='close-modal')return $('#modal').close();
  if(a==='tab'){view.tab=value;refresh();} else if(a==='layout'){view.layout=value;refresh();}else if(a==='clear-filters'){view.search='';view.movement='all';view.cr='all';refresh();}
  else if(a==='edit-character')editCharacter();else if(a==='manage-forms')manageForms();else if(a==='beast-details')details(key);else if(a==='sources')sources();else if(a==='image-credits')showImageCredits(value);else if(a==='short-rest'||a==='long-rest')restDialog(a==='short-rest'?'short':'long');
  else if(a==='favorite'){state.favorites=state.favorites.includes(key)?state.favorites.filter(k=>k!==key):[...state.favorites,key];save();refresh();if($('#modal').open)details(key);}
  else if(a==='transform'){const b=getBeast(key),next=b&&transform(state,b);if(!next)return toast('This form is unavailable. Check your known forms and remaining uses.');state=next;log('Transformed into '+b.name+'.');$('#modal').close();refresh();toast('You take the shape of '+b.name+'.');}
  else if(a==='revert'){state.active=null;log('Returned to normal form.');refresh();toast('Returned to your own skin. Temporary HP lasts until used or your Long Rest.');}
  else if(['damage','heal','temp-hp'].includes(a))amountDialog(a);
  else if(a==='spend-slot'||a==='restore-slot'){const i=Number(value);state.slots[i]=Math.max(0,Math.min(p().slots[i],state.slots[i]+(a==='spend-slot'?-1:1)));log(`${a==='spend-slot'?'Spent':'Restored'} a level ${i+1} spell slot.`);refresh();}
  else if(a==='end-concentration'){state.concentration='';save();refresh();}
  else if(a==='prepare-spell'){const s=spells.find(s=>s.key===key);if(!s)return;if(state.prepared.includes(s.name))state.prepared=state.prepared.filter(n=>n!==s.name);else{if(state.prepared.length>=p().prepared)return toast('Your regular prepared spell limit is '+p().prepared+'.');state.prepared.push(s.name);}save();refresh();}
  else if(a==='learn-cantrip'){const s=spells.find(s=>s.key===key);if(!s||s.level)return;if(state.cantrips.includes(s.name))state.cantrips=state.cantrips.filter(n=>n!==s.name);else{if(state.cantrips.length>=cantripLimit())return toast('You can learn '+cantripLimit()+' regular cantrips.');state.cantrips.push(s.name);}save();refresh();}else if(a==='spell-detail')spellDetail(key);else if(a==='cast')castDialog(key);
  else if(a==='roll'||a==='roll-ability'){const roll=crypto.getRandomValues(new Uint32Array(1))[0]%20+1;const bonus=a==='roll-ability'?mod((active()?effectiveAbilities(active(),state):state.abilities)[value]):0;const message=a==='roll-ability'?`${value}: ${roll} ${signed(bonus)} = ${roll+bonus}`:`d20: ${roll}`;log('Rolled '+message);toast(message);refresh();}
  else if(a==='resurge'){if(state.uses||state.level<5)return;const opts=state.slots.map((n,i)=>n?`<option value="${i}">Level ${i+1} · ${n} left</option>`:'').join('');if(!opts)return toast('No spell slots remain.');modal('Wild Resurgence',`<form id="resurge-form"><p>Spend a slot to regain one Wild Shape use. You can do this once on each of your turns, when you have no uses remaining.</p><label class="field">Spell slot<select name="slot">${opts}</select></label><div class="modal-footer">${btn('Cancel','close-modal')}<button class="button primary" type="submit">Restore one use</button></div></form>`);}
  else if(a==='recover-slot'){if(state.level>=5&&!state.resurgenceUsed&&state.uses&&state.slots[0]<p().slots[0]){state.uses--;state.slots[0]++;state.resurgenceUsed=true;log('Wild Resurgence: restored a level 1 slot.');refresh();}}
  else if(a==='moon-step'){if(state.level>=10&&state.moonSteps>0){state.moonSteps--;log('Used Moonlight Step.');refresh();toast('Teleport up to 30 feet. Your next attack this turn has Advantage.');}}
  else if(a==='new-entry')modal('New journal entry',`<form id="entry-form"><label class="field">Title<input name="title" maxlength="100" placeholder="Under the silver branches" required></label><label class="field">Your story<textarea name="body" rows="7" required placeholder="What will you remember?"></textarea></label><div class="modal-footer">${btn('Cancel','close-modal')}<button class="button primary" type="submit">Save entry</button></div></form>`);
  else if(a==='delete-entry')modal('Remove this journal entry?',`<p>This will remove “${esc(state.entries[Number(value)]?.title)}” from your saved journal.</p><div class="modal-footer">${btn('Keep entry','close-modal')}${btn('Delete entry','confirm-delete','danger',`data-value="${value}"`)}</div>`);
  else if(a==='confirm-delete'){state.entries.splice(Number(value),1);save();$('#modal').close();refresh();}
  else if(a==='backup'){pendingBackup=null;modal('Restore a character backup',`<p>Choose a Moonwild JSON export from this device. You can review its character before replacing the current save.</p><label class="field">Character backup<input id="backup-file" type="file" accept=".json,application/json"></label><div id="backup-preview"></div><div class="modal-footer">${btn('Export current save','export')}${btn('Cancel','close-modal')}${btn('Restore character','restore-backup','primary','disabled id="restore-backup-button"')}</div>`);}else if(a==='restore-backup'){if(!pendingBackup)return;state=pendingBackup;pendingBackup=null;log('Restored character backup.');$('#modal').close();refresh();toast('Character restored.');}else if(a==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='moonwild-character.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Character backup exported.');}
});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='form-search'){view.search=t.value;updateForms();}if(t.id==='spell-search'){view.spellSearch=t.value;updateSpells();}if(t.id==='equipment-notes'){state.equipment=t.value;save();}if(t.id==='campaign-notes'){state.notes=t.value;save();}if(t.id==='concentration'){state.concentration=t.value;save();}if(t.closest('#known-form')){const n=$$('#known-form input:checked').length;$('#known-count').textContent=`${n} / ${p().known} selected`;}});
const $$=s=>Array.from(document.querySelectorAll(s));
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='backup-file'){pendingBackup=null;$('#restore-backup-button').disabled=true;try{const file=t.files[0];if(!file)return;if(file.size>2000000)throw Error('Choose a backup smaller than 2 MB.');const raw=JSON.parse(await file.text());if(raw.version!==1||typeof raw.name!=='string'||!raw.abilities||!Array.isArray(raw.known))throw Error('This is not a valid Moonwild character backup.');pendingBackup=normalize(raw);$('#backup-preview').innerHTML='<div class="source-card"><h3>'+esc(pendingBackup.name)+'</h3><p>Level '+pendingBackup.level+' · '+esc(pendingBackup.species)+' · '+pendingBackup.known.length+' known forms. Restoring replaces the character saved in this browser.</p></div>';$('#restore-backup-button').disabled=false;}catch(err){$('#backup-preview').textContent=err.message;}return;}if(t.id==='movement-filter'){view.movement=t.value;updateForms();}if(t.id==='cr-filter'){view.cr=t.value;updateForms();}if(t.id==='sort-forms'){view.sort=t.value;updateForms();}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);
  if(f.id==='character-form'){const old=p();const level=Number(d.get('level'));state={...state,name:d.get('name').trim(),species:d.get('species').trim(),background:d.get('background').trim(),level,maxHP:Number(d.get('maxHP')),ac:Number(d.get('ac')),primalOrder:d.get('primalOrder'),abilities:Object.fromEntries(ABILITIES.map(a=>[a,Number(d.get(a))]))};state=normalize(state);if(progression(level).uses>old.uses)toast('New resource limits unlocked. Complete a rest to recharge.');log('Updated character sheet.');}
  else if(f.id==='known-form'){const known=d.getAll('known');if(known.length>p().known)return toast(`Choose at most ${p().known} forms.`);state.known=known;if(!known.includes(state.active))state.active=null;log('Updated known forms during setup / level-up.');}
  else if(f.id==='rest-form'){const forget=d.get('forget'),learn=d.get('learn');if(Boolean(forget)!==Boolean(learn))return toast('Choose both a form to forget and a form to learn, or leave both blank.');if(forget&&learn)state.known=state.known.map(k=>k===forget?learn:k);state=rest(state,f.dataset.type);log(`Completed a ${f.dataset.type==='long'?'Long':'Short'} Rest.`);toast('Rest complete. Your resources are refreshed.');}
  else if(f.id==='amount-form'){const n=Number(d.get('amount')),type=f.dataset.type;if(type==='damage'){const concentrated=state.concentration;state=takeDamage(state,n);log(`Took ${n} damage.`);if(concentrated&&state.hp>0)toast(`Concentration: make a DC ${Math.min(30,Math.max(10,Math.floor(n/2)))} Constitution save${active()&&state.level>=6?' (Moon Wisdom bonus applies)':''}.`);}else if(type==='heal'){state.hp=Math.min(state.maxHP,state.hp+n);log(`Healed ${n} HP (up to maximum).`);}else{state.tempHP=n;save();}}
  else if(f.id==='entry-form'){state.entries.unshift({title:d.get('title').trim(),body:d.get('body').trim(),at:new Date().toISOString()});save();}
  else if(f.id==='cast-form'){const s=spells.find(s=>s.key===f.dataset.key),i=Number(d.get('slot'));if(!s||!state.slots[i]||i<s.level-1)return toast('That spell slot is unavailable.');state.slots[i]--;if(s.concentration)state.concentration=s.name;log(`Cast ${s.name} with a level ${i+1} slot.`);toast(s.name+' cast. Resolve its effect at the table.');}
  else if(f.id==='resurge-form'){const i=Number(d.get('slot'));if(state.uses||!state.slots[i])return;state.slots[i]--;state.uses=1;log('Wild Resurgence: regained one Wild Shape use.');}
  else return;
  save();$('#modal').close();refresh();
});
window.addEventListener('hashchange',()=>{refresh();window.scrollTo(0,0);});
document.addEventListener('keydown',e=>{if(e.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('[role=tab]');let i=tabs.indexOf(e.target);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;view.tab=tabs[i].dataset.value;refresh();$$('[role=tab]')[i].focus();return;}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();$('#form-search')?.focus();}});
setInterval(()=>{if($('#shape-timer'))$('#shape-timer').textContent=remainingTime();if(state?.active&&state.shiftedAt&&Date.now()-state.shiftedAt>=p().hours*3600000){state.active=null;save();refresh();toast('Your Wild Shape duration has ended.');}},10000);
async function boot(){try{const responses=await Promise.all([fetch('./data/beasts.json'),fetch('./data/spells.json')]);if(responses.some(r=>!r.ok))throw Error('Data could not be loaded.');const [b,s]=await Promise.all(responses.map(r=>r.json()));beasts=b.filter(b=>!b.name.startsWith('Swarm of'));spells=s;try{const raw=localStorage.getItem(KEY);state=raw?normalize(JSON.parse(raw)):defaultState();}catch{state=defaultState();}if(state.active&&Date.now()-(state.shiftedAt||0)>=p().hours*3600000)state.active=null;save();refresh();}catch(err){$('#app').innerHTML=`<div class="loading"><h1>The path is a little overgrown.</h1><p>${esc(err.message)}</p><p>Start the app with <code>npm start</code> and open <a href="http://127.0.0.1:4173">localhost:4173</a>.</p><button class="button primary" onclick="location.reload()">Try again</button></div>`;}}
boot();
